<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VEDAIRO Admin</title><style>body{font-family:system-ui;background:#f5f7fb;margin:0}.wrap{max-width:1200px;margin:40px auto;padding:20px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:18px}.card{background:white;padding:25px;border-radius:14px;box-shadow:0 4px 20px #0001}.n{font-size:32px;font-weight:700}</style></head><body><div class="wrap"><h1>VEDAIRO Enterprise Admin</h1><div class="grid"><?php foreach($data as $k=>$v):?><div class="card"><div><?=htmlspecialchars(ucwords(str_replace('_',' ',$k)))?></div><div class="n"><?=htmlspecialchars((string)$v)?></div></div><?php endforeach;?></div></div></body></html>
